globalThis.contractLoads?.push('EP_ONLY');
export async function GET(ctx) {globalThis.contractCalls?.push('EP_ONLY:'+ctx.url.pathname);
if('EP_ONLY'!=='REST_ONLY'&&ctx.url.searchParams.has('throw'))throw new Error('CONTRACT_THROW_EP_ONLY');
if(ctx.url.searchParams.has('own404'))return new Response('OWN_404',{status:404});
const target=ctx.url.searchParams.get('to'); if(target)return ctx.rewrite(target);
return new Response('EP_ONLY|'+ctx.url.pathname+'|'+JSON.stringify(ctx.params)+'|'+(ctx.locals.trace??''));}

