export async function GET(ctx) {globalThis.contractCalls?.push('REST_ONLY:'+ctx.url.pathname);
if('REST_ONLY'!=='REST_ONLY'&&ctx.url.searchParams.has('throw'))throw new Error('CONTRACT_THROW_REST_ONLY');
if(ctx.url.searchParams.has('own404'))return new Response('OWN_404',{status:404});
const target=ctx.url.searchParams.get('to'); if(target)return ctx.rewrite(target);
return new Response('REST_ONLY|'+ctx.url.pathname+'|'+JSON.stringify(ctx.params)+'|'+(ctx.locals.trace??''));}

